window.QUESTIONS=[
 {"id":"senales-1","cat":"senales","q":"La señal PARE (octágono rojo) obliga a:","opts":["Reducir la velocidad y pasar si no viene nadie","Detenerse por completo antes de la línea, ceder el paso y avanzar solo cuando sea seguro","Tocar la bocina y continuar"],"correct":1,"exp":"Es la única señal con forma de octágono. Exige detención TOTAL, no basta reducir. Avanzas solo cuando la vía está despejada."},
 {"id":"senales-2","cat":"senales","q":"Una señal con forma de rombo y fondo amarillo es de tipo:","opts":["Reglamentaria (prohíbe u obliga)","Preventiva (advierte un peligro)","Informativa (orienta)"],"correct":1,"exp":"Amarillo en rombo = preventiva. Te avisa de un riesgo próximo (curva, cruce, niños) para que te prepares."},
 {"id":"senales-3","cat":"senales","q":"Las señales reglamentarias (fondo blanco con orla roja) sirven para:","opts":["Imponer prohibiciones u obligaciones","Indicar servicios cercanos","Sugerir una velocidad recomendada"],"correct":0,"exp":"Reglamentarias = mandato. No cumplirlas es infracción (ej: 'No entrar', 'Prohibido virar', límite de velocidad)."},
 {"id":"senales-4","cat":"senales","q":"Ante la señal CEDA EL PASO (triángulo invertido), debes:","opts":["Detenerte siempre por completo como en un PARE","Ceder el paso a la vía preferente, deteniéndote solo si es necesario","Continuar, tú siempre tienes preferencia"],"correct":1,"exp":"A diferencia del PARE, aquí no siempre te detienes: si la vía está libre continúas; si viene otro, cedes."},
 {"id":"senales-5","cat":"senales","q":"Una línea central continua en la calzada indica que:","opts":["Puedes adelantar con precaución","Está prohibido cruzarla o adelantar","Es solo decorativa"],"correct":1,"exp":"Línea continua = no la cruces ni adelantes. La segmentada sí permite adelantar cuando hay buena visibilidad."},
 {"id":"senales-6","cat":"senales","q":"Ante un semáforo en luz amarilla, lo correcto es:","opts":["Acelerar para alcanzar a pasar","Detenerte si puedes hacerlo con seguridad","Ignorarla, equivale a verde"],"correct":1,"exp":"El amarillo anuncia el rojo: prepárate a parar. Acelerar para 'ganarle' causa muchos choques en las esquinas."},
 {"id":"senales-7","cat":"senales","q":"Las señales informativas (fondo azul o verde) sirven para:","opts":["Orientar y guiar (destinos, servicios, sentidos)","Prohibir maniobras","Advertir peligros inmediatos"],"correct":0,"exp":"Azul/verde = información. No mandan ni advierten peligro: te ubican en la ruta (salidas, hospitales, ciudades)."},
 {"id":"senales-8","cat":"senales","q":"Un semáforo con luz roja intermitente (que parpadea) equivale a:","opts":["Seguir con precaución","Una señal PARE: detención total","Que el semáforo está descompuesto y no aplica"],"correct":1,"exp":"Rojo intermitente = PARE. Debes detenerte por completo y avanzar cuando sea seguro."},
 {"id":"senales-9","cat":"senales","q":"Un semáforo con luz amarilla intermitente indica:","opts":["Detención total obligatoria","Avanzar con precaución, cediendo el paso","Prohibido pasar"],"correct":1,"exp":"Amarillo parpadeante = precaución. Reduce, mira bien y cruza cediendo el paso; no exige detenerte del todo."},
 {"id":"senales-10","cat":"senales","q":"Una señal en forma de aspa (cruz de San Andrés) advierte:","opts":["Un cruce de peatones","Un cruce ferroviario a nivel","El fin de una autopista"],"correct":1,"exp":"Marca un cruce con vía de tren. El tren SIEMPRE tiene preferencia: nunca cruces con la barrera baja o la luz activa."},
 {"id":"senales-11","cat":"senales","q":"Las flechas pintadas en el pavimento de una pista indican:","opts":["Una decoración de la calzada","El sentido o los virajes obligatorios de esa pista","Zona de estacionamiento"],"correct":1,"exp":"Te dicen qué maniobra puedes hacer desde esa pista. Ubícate con tiempo en la pista correcta."},
 {"id":"senales-12","cat":"senales","q":"Una señal circular con fondo rojo y una barra blanca horizontal significa:","opts":["Estacionamiento permitido","No entrar / dirección prohibida","Ceda el paso"],"correct":1,"exp":"Es 'No entre': prohíbe el ingreso a esa vía (típico de calles de un sentido). Ignorarla es infracción grave."},
 {"id":"senales-13","cat":"senales","q":"Una línea segmentada (a trazos) en la calzada indica que:","opts":["Nunca se puede cruzar","Se permite adelantar o cambiar de pista cuando es seguro","Es exclusiva para buses"],"correct":1,"exp":"La discontinua permite cruzarla para adelantar o cambiar de pista, con visibilidad. La continua, no."},
 {"id":"senales-14","cat":"senales","q":"Una señal preventiva de 'Zona de escuela' te indica que debes:","opts":["Acelerar para pasar rápido","Reducir la velocidad y extremar la atención por niños","Tocar la bocina"],"correct":1,"exp":"Anticipa presencia de niños. En horario de entrada/salida el máximo es 30 km/h; los niños son impredecibles."},
 {"id":"senales-15","cat":"senales","q":"Una señal reglamentaria de 'No adelantar' significa que:","opts":["Puedes adelantar con cuidado","Está prohibido adelantar en ese tramo","Solo pueden adelantar los camiones"],"correct":1,"exp":"Prohíbe rebasar en ese sector (curvas, poca visibilidad, riesgo). Espera hasta que la señal termine o la vía lo permita."},
 {"id":"senales-16","cat":"senales","q":"Una señal preventiva con una flecha en curva te advierte que:","opts":["Viene una curva: reduce y no adelantes","La calle termina","Hay estacionamiento"],"correct":0,"exp":"Anuncia una curva peligrosa. Baja la velocidad antes de entrar; frenar dentro de la curva te hace perder el control."},
 {"id":"senales-17","cat":"senales","q":"Una señal preventiva de 'resalto' o 'lomo de toro' indica que:","opts":["Puedes acelerar","Hay un resalto en la calzada: reduce la velocidad","La vía está en mal estado permanente"],"correct":1,"exp":"Avisa de un badén o lomo de toro. Pásalo lento: a velocidad daña el vehículo y descontrola la dirección."},
 {"id":"senales-18","cat":"senales","q":"Una señal circular blanca con orla roja y un número (por ejemplo 60) indica:","opts":["Una velocidad recomendada","La velocidad máxima obligatoria en ese tramo","La distancia a la próxima ciudad"],"correct":1,"exp":"Es reglamentaria: fija el máximo legal de ese tramo. Superarlo es infracción, aunque te sientas seguro."},
 {"id":"senales-19","cat":"senales","q":"Una señal de 'Prohibido estacionar' significa que:","opts":["Puedes detenerte un rato","No puedes dejar el vehículo estacionado allí","Solo se prohíbe de noche"],"correct":1,"exp":"No dejes el auto detenido en ese sector. Pueden cursarte parte y hasta retirar el vehículo con grúa."},
 {"id":"senales-20","cat":"senales","q":"Una señal reglamentaria de 'sentido único' (flecha) indica que:","opts":["La vía es de un solo sentido; prohibido ir en contra","Puedes ir en cualquier dirección","Es una calle sin salida"],"correct":0,"exp":"El tránsito va en una sola dirección. Ir en contra es de las infracciones más peligrosas (riesgo de choque frontal)."},
 {"id":"senales-21","cat":"senales","q":"Un semáforo con la figura de un peatón regula:","opts":["A los vehículos","A los peatones","A los ciclistas solamente"],"correct":1,"exp":"Ordena el cruce de los peatones. Aun así, si un peatón va cruzando, el conductor debe cederle el paso."},
 {"id":"senales-22","cat":"senales","q":"Una señal preventiva con la figura de personas caminando advierte:","opts":["Zona de estacionamiento","Posible cruce de peatones: reduce y prepárate a ceder","Fin de la acera"],"correct":1,"exp":"Anticipa que puede haber peatones cruzando. Baja la velocidad para poder detenerte a tiempo."},
 {"id":"velocidad-1","cat":"velocidad","d":true,"q":"¿Cuál es la velocidad máxima en zona urbana en Chile?","opts":["60 km/h","50 km/h","40 km/h"],"correct":1,"exp":"La Ley 21.492 bajó el máximo urbano de 60 a 50 km/h. A menor velocidad, un peatón atropellado tiene muchas más chances de sobrevivir."},
 {"id":"velocidad-2","cat":"velocidad","d":true,"q":"En una zona escolar señalizada, en horario de entrada y salida de alumnos, la velocidad máxima habitual es:","opts":["50 km/h","40 km/h","30 km/h"],"correct":2,"exp":"30 km/h en zona escolar durante el ingreso/egreso. Es un tramo crítico donde los niños cruzan sin avisar."},
 {"id":"velocidad-3","cat":"velocidad","d":true,"q":"En un camino rural con una sola pista por sentido, la velocidad máxima para autos es:","opts":["80 km/h","100 km/h","120 km/h"],"correct":1,"exp":"100 km/h en rural de una pista por sentido. Los 120 son solo para vías de dos o más pistas en el mismo sentido."},
 {"id":"velocidad-4","cat":"velocidad","d":true,"q":"En una autopista con dos o más pistas en un mismo sentido, la velocidad máxima para autos es:","opts":["100 km/h","120 km/h","140 km/h"],"correct":1,"exp":"120 km/h es el tope para autos. Buses y camiones pesados tienen límites menores (90–100)."},
 {"id":"velocidad-5","cat":"velocidad","d":true,"q":"Superar el límite de velocidad en más de 20 km/h se considera:","opts":["Infracción leve","Infracción grave","Infracción gravísima"],"correct":2,"exp":"Escala: hasta 10 km/h = menos grave; 11 a 20 = grave; más de 20 = GRAVÍSIMA. Ej: ir a 71+ donde el límite es 50."},
 {"id":"velocidad-6","cat":"velocidad","d":true,"q":"Con lluvia o neblina, aunque el límite sea 100 km/h, debes:","opts":["Mantener el límite máximo, es legal","Reducir a una velocidad razonable y prudente según las condiciones","Acelerar para salir de la zona peligrosa"],"correct":1,"exp":"El límite es un máximo, no una obligación. Siempre adecúa la velocidad a la visibilidad y al piso. Ir al tope bajo lluvia igual es infracción."},
 {"id":"velocidad-7","cat":"velocidad","d":true,"q":"Al acercarte a un cruce o intersección, aunque tengas preferencia, debes:","opts":["Mantener tu velocidad","Reducir la velocidad y estar atento","Acelerar para pasar rápido"],"correct":1,"exp":"Tener preferencia no es tener el paso libre. Baja la velocidad: el otro podría no respetar su señal."},
 {"id":"velocidad-8","cat":"velocidad","d":true,"q":"Respecto a la velocidad mínima, la ley señala que:","opts":["No existe límite mínimo","No debes ir tan lento que obstruyas el tránsito normal","Puedes ir a la velocidad que quieras"],"correct":1,"exp":"Ir demasiado lento sin motivo también es infracción y genera riesgo, porque obliga a otros a maniobras bruscas."},
 {"id":"velocidad-9","cat":"velocidad","d":true,"q":"Los camiones de carga pesada y el transporte escolar tienen, en general, un límite de velocidad:","opts":["Igual al de los autos","Menor que el de los autos","Mayor, por su tamaño"],"correct":1,"exp":"Por su peso y distancia de frenado, van más lento (ej. 90 km/h). Un vehículo pesado necesita muchos más metros para detenerse."},
 {"id":"alcohol-1","cat":"alcohol","d":true,"q":"Se considera 'conducción bajo la influencia del alcohol' cuando la alcoholemia está entre:","opts":["0,1 y 0,3 g/L","0,3 y menos de 0,8 g/L","0,8 y 1,0 g/L"],"correct":1,"exp":"Tramo 0,3 a 0,79 g/L = bajo la influencia. Desde 0,8 g/L ya es 'estado de ebriedad', con penas mayores."},
 {"id":"alcohol-2","cat":"alcohol","d":true,"q":"¿Desde qué nivel de alcohol en la sangre se configura el 'estado de ebriedad'?","opts":["0,5 g/L","0,8 g/L","1,0 g/L"],"correct":1,"exp":"Desde 0,8 g/L inclusive. Antes de la Ley 20.580 el umbral era 1,0; se endureció a 0,8."},
 {"id":"alcohol-3","cat":"alcohol","d":true,"q":"La 'Ley de Tolerancia Cero' (Ley 20.580) principalmente:","opts":["Prohíbe todo consumo de alcohol a cualquier persona","Bajó los límites al volante de 0,5/1,0 a 0,3/0,8 g/L y subió las sanciones","Solo aplica a conductores profesionales"],"correct":1,"exp":"Se llama 'tolerancia cero' por la idea de fondo (alcohol y manejo no se mezclan), no porque el límite sea literalmente 0."},
 {"id":"alcohol-4","cat":"alcohol","q":"Primera vez que te sorprenden conduciendo en estado de ebriedad (sin causar daños). La suspensión de licencia es de:","opts":["1 mes","2 años","Solo una multa, sin suspensión"],"correct":1,"exp":"Con la Ley de Tolerancia Cero (20.580), la ebriedad sin daños implica suspensión de 2 años la primera vez, además de multa. Bajo la influencia, 3 meses."},
 {"id":"alcohol-5","cat":"alcohol","d":true,"q":"Un conductor se niega, sin justificación, a hacerse el alcotest. La ley:","opts":["Lo deja libre por falta de prueba","Lo sanciona con multa y suspensión de la licencia","Solo lo multa si causó un accidente"],"correct":1,"exp":"Negarse sin causa justificada a la prueba no te libra: la ley lo sanciona con multa y suspensión de la licencia."},
 {"id":"alcohol-6","cat":"alcohol","d":true,"q":"¿Qué reduce realmente el nivel de alcohol en la sangre?","opts":["Un café cargado o una ducha fría","Comer mucho antes de manejar","Únicamente el paso del tiempo"],"correct":2,"exp":"Solo el hígado metaboliza el alcohol, y a ritmo fijo. Café, ducha o comida NO aceleran nada: solo el tiempo lo baja."},
 {"id":"alcohol-7","cat":"alcohol","d":true,"q":"Conducir bajo el efecto de drogas o estupefacientes:","opts":["No está regulado","Se sanciona igual que conducir con alcohol","Solo es problema si son ilegales"],"correct":1,"exp":"La ley sanciona manejar drogado igual que ebrio. Las drogas alteran reflejos y percepción tanto o más que el alcohol."},
 {"id":"alcohol-8","cat":"alcohol","d":true,"q":"Algunos medicamentos (antialérgicos, relajantes, para el sueño) pueden:","opts":["Mejorar tu concentración al volante","Producir somnolencia y afectar la conducción","No tener ningún efecto"],"correct":1,"exp":"Muchos dan sueño o bajan los reflejos. Lee el prospecto o pregunta al médico antes de manejar."},
 {"id":"alcohol-9","cat":"alcohol","d":true,"q":"El alcohol afecta la conducción principalmente porque:","opts":["Mejora la visión nocturna","Aumenta el tiempo de reacción y reduce el juicio y los reflejos","Solo da sueño"],"correct":1,"exp":"Reaccionas más lento, calculas mal las distancias y te sientes 'seguro' cuando no lo estás. Por eso es tan peligroso."},
 {"id":"alcohol-10","cat":"alcohol","d":true,"q":"Si vas a beber, la forma segura de volver es:","opts":["Manejar despacio y con cuidado","Designar un conductor que no beba, o usar taxi/transporte","Esperar 15 minutos y manejar"],"correct":1,"exp":"Si tomaste, no manejas. Punto. Conductor designado, taxi o app: cualquiera es más barato que un accidente o la cárcel."},
 {"id":"alcohol-11","cat":"alcohol","d":true,"q":"Manejar a la mañana siguiente de haber bebido mucho:","opts":["Es 100% seguro, ya pasó la noche","Aún puede dar positivo, porque el alcohol tarda horas en eliminarse","Solo afecta si sigues bebiendo"],"correct":1,"exp":"La 'caña' o resaca puede seguir marcando alcohol en sangre. Si dormiste pocas horas tras beber fuerte, mejor no manejes."},
 {"id":"alcohol-12","cat":"alcohol","d":true,"q":"Mezclar alcohol con medicamentos al conducir:","opts":["Se anulan entre sí","Potencia los efectos y es aún más peligroso","No cambia nada"],"correct":1,"exp":"La mezcla multiplica la somnolencia y la pérdida de reflejos. Es una combinación especialmente riesgosa al volante."},
 {"id":"sri-1","cat":"sri","d":true,"q":"Los niños y niñas menores de 12 años deben viajar:","opts":["En el asiento delantero para vigilarlos","Siempre en el asiento trasero","Donde haya espacio"],"correct":1,"exp":"Menores de 12 SIEMPRE atrás, con cinturón o silla adecuada. En un choque frontal la energía es mucho mayor adelante."},
 {"id":"sri-2","cat":"sri","d":true,"q":"El sistema de retención infantil (silla o alzador) es obligatorio hasta que el niño:","opts":["Cumpla 4 años","Cumpla 9 años (o llegue a 135 cm y 33 kg)","Cumpla 6 años"],"correct":1,"exp":"Obligatorio hasta cumplir 9 años, o hasta 135 cm y 33 kg. Recién ahí usa solo cinturón, pero sigue atrás hasta los 12."},
 {"id":"sri-3","cat":"sri","d":true,"q":"Llevar a un menor de 12 años en el asiento delantero se considera:","opts":["Falta leve","Falta grave","Falta gravísima (multa 1,5 a 3 UTM y suspensión de licencia)"],"correct":2,"exp":"Es GRAVÍSIMA: multa de 1,5 a 3 UTM y suspensión de licencia de 5 a 45 días. Igual sanción por menor de 9 sin su silla."},
 {"id":"sri-4","cat":"sri","d":true,"q":"¿Por qué es peligrosa una silla infantil frente a un airbag delantero activo?","opts":["El airbag puede golpear violentamente al niño al inflarse","El niño no ve por la ventana","No hay ningún riesgo"],"correct":0,"exp":"Los airbags están hechos para adultos; al desplegarse pueden lesionar gravemente a un niño. Por eso van atrás."},
 {"id":"sri-5","cat":"sri","d":true,"q":"¿En qué caso excepcional un menor podría ir adelante?","opts":["Cuando el viaje es corto","Cuando el vehículo no tiene asientos traseros (ej: cabina simple)","Cuando va dormido"],"correct":1,"exp":"La única excepción es un vehículo sin asientos traseros. Ahí se desactiva el airbag y se usa la silla adecuada."},
 {"id":"sri-6","cat":"sri","d":true,"q":"Un bebé recién nacido debe viajar en:","opts":["Los brazos de un adulto atrás","Una silla mirando hacia atrás (a contramarcha), en el asiento trasero","Un cojín común con cinturón"],"correct":1,"exp":"A contramarcha protege mejor la cabeza y el cuello del bebé en un choque. Llevarlo en brazos es inútil: sale despedido."},
 {"id":"sri-7","cat":"sri","d":true,"q":"La silla infantil debe estar:","opts":["Solo apoyada en el asiento","Certificada y bien anclada, sin holgura excesiva","Cubierta con una manta gruesa"],"correct":1,"exp":"Debe ser un modelo acreditado y quedar firme (no debe moverse mucho). Mal anclada, no protege en el impacto."},
 {"id":"conducta-1","cat":"conducta","q":"¿Por qué parte de la vía debe circular normalmente un vehículo?","opts":["Por la berma","Por la calzada","Por la acera"],"correct":1,"exp":"La calzada es para los vehículos. La acera es del peatón y la berma es franja de emergencia, no pista de circulación."},
 {"id":"conducta-2","cat":"conducta","q":"Circular por la berma está permitido:","opts":["Cuando hay tráfico y quieres adelantar","Solo por emergencia o avería que te obligue a detenerte","Siempre que vayas con cuidado"],"correct":1,"exp":"La berma es zona de resguardo. Usarla para 'ganar tiempo' es infracción y peligroso para quien está detenido allí."},
 {"id":"conducta-3","cat":"conducta","q":"El cinturón de seguridad es obligatorio para:","opts":["Solo el conductor","Solo los asientos delanteros","Todos los ocupantes, adelante y atrás"],"correct":2,"exp":"Todos, en todos los asientos. Un pasajero de atrás sin cinturón se vuelve un proyectil que puede matar a los de adelante."},
 {"id":"conducta-4","cat":"conducta","q":"El uso del teléfono celular mientras se conduce:","opts":["Se permite para mensajes cortos","Está prohibido, salvo con sistema de manos libres","Se permite en semáforos en rojo"],"correct":1,"exp":"Prohibido manipularlo; solo manos libres. Escribir al volante te distrae tanto como conducir con alcohol."},
 {"id":"conducta-5","cat":"conducta","q":"El adelantamiento a otro vehículo se hace, por regla general:","opts":["Por la derecha","Por la izquierda, con visibilidad y sin línea continua","Por donde haya espacio"],"correct":1,"exp":"Se adelanta por la izquierda, solo cuando ves claro el sentido contrario y la señalización lo permite."},
 {"id":"conducta-6","fig":"dia_distancia","cat":"conducta","q":"Para una distancia de seguimiento segura respecto al auto de adelante:","opts":["Ir lo más pegado posible","Dejar al menos 2 a 3 segundos de separación","La distancia no importa si vas lento"],"correct":1,"exp":"La regla de los 2–3 segundos (más si está mojado) te da margen para frenar. Ir pegado causa choques por alcance."},
 {"id":"conducta-7","cat":"conducta","q":"Al entrar a un túnel o con neblina densa debes:","opts":["Encender las luces altas","Encender las luces bajas","Apagar todas las luces"],"correct":1,"exp":"Luces bajas: iluminan sin encandilar. Las altas en neblina rebotan y te enceguecen a ti mismo."},
 {"id":"conducta-8","img":"dia_rotonda","cat":"conducta","q":"En una rotonda (glorieta), la preferencia la tiene:","opts":["El que va a entrar","El vehículo que ya circula dentro de la rotonda","El de mayor tamaño"],"correct":1,"exp":"Quien ya está dentro pasa primero; el que entra cede. Así el anillo no se bloquea."},
 {"id":"conducta-9","cat":"conducta","q":"Antes de cambiar de pista debes:","opts":["Solo mirar el retrovisor central","Señalizar con el intermitente y revisar el punto ciego","Cambiarte rápido para no molestar"],"correct":1,"exp":"El espejo no muestra todo: hay un 'punto ciego' a los costados. Señaliza y gira la cabeza un instante antes de cambiarte."},
 {"id":"conducta-10","cat":"conducta","q":"La bocina debe usarse para:","opts":["Apurar a los demás","Prevenir un accidente o advertir un peligro","Saludar o expresar molestia"],"correct":1,"exp":"La bocina es una herramienta de seguridad, no de desahogo. Usarla para presionar solo aumenta la tensión y el riesgo."},
 {"id":"conducta-11","cat":"conducta","q":"Al acercarte a un paso peatonal debes:","opts":["Mantener la velocidad","Reducir y estar listo para ceder el paso","Acelerar antes de que crucen"],"correct":1,"exp":"Anticipa: baja la velocidad para poder detenerte. El peatón puede aparecer de golpe entre autos estacionados."},
 {"id":"conducta-12","cat":"conducta","q":"Conducir en contra del sentido del tránsito (por la pista contraria) es:","opts":["Permitido si no viene nadie","Una infracción gravísima","Una falta leve"],"correct":1,"exp":"Es gravísima y de las más letales: un choque frontal suma ambas velocidades. Nunca inviertas el sentido."},
 {"id":"conducta-13","cat":"conducta","q":"Si hay congestión y el cruce está bloqueado, debes:","opts":["Entrar igual al cruce para avanzar","No entrar al cruce si no puedes salir de él","Tocar la bocina y forzar el paso"],"correct":1,"exp":"Quedarte 'atravesado' en la intersección la bloquea para todos, incluidas ambulancias. No entres si no puedes despejarla."},
 {"id":"conducta-14","cat":"conducta","q":"Ante un vehículo detenido con las luces de emergencia encendidas en la vía:","opts":["Adelantarlo a la misma velocidad","Reducir y pasar dejando espacio, con precaución","Tocar la bocina para que se mueva"],"correct":1,"exp":"Las balizas avisan de un problema. Baja la velocidad y déjale distancia: puede haber personas alrededor del auto."},
 {"id":"conducta-15","cat":"conducta","q":"Comer, maquillarse o programar el GPS mientras manejas:","opts":["Es aceptable si vas lento","Son distracciones peligrosas; detente para hacerlo","No afectan la conducción"],"correct":1,"exp":"Cualquier cosa que te saque los ojos o las manos del manejo es un riesgo. Si necesitas hacerlo, estaciónate primero."},
 {"id":"conducta-16","cat":"conducta","q":"Llevar una mascota suelta dentro del auto:","opts":["No tiene ningún riesgo","Es peligroso: distrae y en un choque sale disparada; debe ir asegurada","Solo importa en viajes largos"],"correct":1,"exp":"Un animal suelto te distrae y, en un frenazo, se convierte en proyectil. Llévalo con arnés o en un transportín fijo."},
 {"id":"conducta-17","cat":"conducta","q":"La carga u objetos dentro del vehículo deben:","opts":["Ir sueltos, no pasa nada","Ir bien asegurados; sueltos se vuelven proyectiles en un frenazo","Ir siempre en el asiento delantero"],"correct":1,"exp":"Una botella o herramienta suelta, en un choque, vuela a gran velocidad. Asegura la carga en la maleta o con sujeción."},
 {"id":"conducta-18","cat":"conducta","q":"Usar audífonos que tapen ambos oídos mientras conduces:","opts":["Está bien si el volumen es bajo","Es peligroso y desaconsejado: no oyes bocinas ni sirenas","Solo se prohíbe a motociclistas"],"correct":1,"exp":"El oído te avisa de peligros que no ves. Taparlo por completo te deja sordo ante una ambulancia o un bocinazo de alerta."},
 {"id":"conducta-19","cat":"conducta","q":"Lo correcto respecto a las manos y el volante es:","opts":["Manejar con una mano para ir cómodo","Mantener ambas manos en el volante y evitar distracciones","Soltar el volante en rectas"],"correct":1,"exp":"Ambas manos te dan control para reaccionar. Manejar con una mano y el celular en la otra multiplica el riesgo."},
 {"id":"conducta-20","cat":"conducta","q":"Circular con más pasajeros o carga de la que permite el vehículo:","opts":["No influye en nada","Afecta la estabilidad y el frenado; debes respetar la capacidad","Solo es problema en autopista"],"correct":1,"exp":"El sobrepeso alarga el frenado y desestabiliza el auto. Respeta la capacidad de asientos y de carga del vehículo."},
 {"id":"paso-1","img":"dia_cruce","cat":"paso","q":"En un cruce sin señales ni semáforo, si llegan dos vehículos a la vez, la preferencia es para:","opts":["El que viene por la derecha","El que viene por la izquierda","El más rápido"],"correct":0,"exp":"Regla de la derecha: sin señalización y en igualdad, cede el que tiene al otro por su lado derecho. En el diagrama, B viene por la derecha de A: B pasa primero."},
 {"id":"paso-2","cat":"paso","q":"Un vehículo de emergencia circula con sirena y balizas encendidas. Debes:","opts":["Mantener tu velocidad y trayecto","Cederle el paso y despejarle la vía","Seguirlo de cerca para avanzar más rápido"],"correct":1,"exp":"Siempre tienen prioridad. Reduce, oríllate y déjale la vía libre. Seguirlo pegado es infracción y peligroso."},
 {"id":"paso-3","cat":"paso","q":"Ante un peatón que cruza por un paso de cebra:","opts":["El peatón siempre tiene la preferencia","El vehículo, si va rápido","Depende de quién llegó primero"],"correct":0,"exp":"En el paso peatonal la prioridad es SIEMPRE del peatón. Debes detenerte y dejarlo cruzar por completo."},
 {"id":"paso-4","cat":"paso","q":"Vas a virar en una esquina y hay peatones cruzando la calle a la que entras. Debes:","opts":["Tocar la bocina para que se apuren","Cederles el paso y esperar","Pasar rápido antes que ellos"],"correct":1,"exp":"El peatón que cruza la vía a la que ingresas tiene preferencia. Virar no te da derecho a pasar sobre él."},
 {"id":"paso-5","cat":"paso","q":"Al salir de un estacionamiento o vía privada hacia la calle, la preferencia la tienen:","opts":["Tú, porque ya vas en movimiento","Los vehículos y peatones que ya circulan por la vía","Nadie, es a quien se atreva primero"],"correct":1,"exp":"Quien se incorpora cede. Los que ya circulan (y los peatones) pasan primero; tú te integras cuando sea seguro."},
 {"id":"paso-6","cat":"paso","q":"En un cruce ferroviario, respecto al tren:","opts":["El auto tiene preferencia si va rápido","El tren siempre tiene preferencia; nunca cruces con barrera baja o luz activa","Pasa el primero que llega"],"correct":1,"exp":"El tren no puede frenar a tiempo ni esquivar. Con barrera baja o luz encendida, jamás cruces. Espera."},
 {"id":"paso-7","cat":"paso","q":"Un bus de transporte escolar está detenido y bajan niños. Debes:","opts":["Adelantarlo rápido","Detenerte o pasar a paso de hombre con máxima precaución","Tocar la bocina"],"correct":1,"exp":"Los niños pueden cruzar por delante o detrás del bus sin mirar. Extrema el cuidado y prepárate para detenerte."},
 {"id":"paso-8","cat":"paso","q":"El semáforo está en verde, pero aún hay peatones terminando de cruzar. Debes:","opts":["Avanzar, tienes verde","Cederles el paso hasta que terminen de cruzar","Avanzar tocando la bocina"],"correct":1,"exp":"El verde te habilita, pero no te autoriza a atropellar. Primero se completa el cruce del peatón."},
 {"id":"paso-9","cat":"paso","q":"Circulas por una vía preferente y otro vehículo espera con señal 'Ceda el paso' para incorporarse. Entonces:","opts":["Debes frenar y cederle","Tú tienes la preferencia y continúas","Ambos deben detenerse"],"correct":1,"exp":"La señal 'Ceda' es para él, no para ti. Tú mantienes tu marcha; él espera un hueco seguro para entrar."},
 {"id":"paso-10","cat":"paso","q":"Una ambulancia está detenida atendiendo una emergencia con sus balizas encendidas. Debes:","opts":["Pasar a tu velocidad normal","Reducir y pasar con precaución, dejando espacio","Tocar la bocina"],"correct":1,"exp":"Puede haber personal o pacientes alrededor. Baja la velocidad y déjale distancia hasta pasarla."},
 {"id":"paso-11","cat":"paso","q":"Un peatón con bastón blanco (persona ciega) va a cruzar. Debes:","opts":["Apurarlo con la bocina","Darle máxima prioridad y esperar con paciencia","Pasar rápido si no te ve"],"correct":1,"exp":"El bastón blanco identifica a una persona con discapacidad visual. Detente por completo y dale todo el tiempo que necesite."},
 {"id":"convivencia-1","fig":"dia_ciclista","cat":"convivencia","q":"Al adelantar a un ciclista, el automovilista debe dejar una distancia lateral mínima de:","opts":["0,5 metro","1 metro","1,5 metros"],"correct":2,"exp":"Mínimo 1,5 metros (Ley 21.088). El ciclista es frágil: un roce a velocidad puede ser mortal. Si no cabe, espera."},
 {"id":"convivencia-2","cat":"convivencia","q":"Por regla general, los ciclistas deben circular por:","opts":["La vereda, junto a los peatones","La ciclovía si existe, o por la calzada","Por donde prefieran"],"correct":1,"exp":"Ciclovía si la hay; si no, la calzada por el costado derecho. La vereda es del peatón, salvo excepciones puntuales."},
 {"id":"convivencia-3","cat":"convivencia","q":"¿Quiénes pueden circular en bicicleta por la vereda como excepción?","opts":["Cualquier persona con casco","Menores de 7 años acompañados, menores de 14 solos, adultos mayores y personas con movilidad reducida","Solo repartidores"],"correct":1,"exp":"Son grupos vulnerables a los que se les permite la vereda, siempre a velocidad de peatón y cediéndoles el paso."},
 {"id":"convivencia-4","cat":"convivencia","q":"Bajo la Ley de Convivencia Vial, el conductor de vehículo motorizado:","opts":["Tiene siempre la razón por ser más grande","Asume mayor responsabilidad frente a peatones y ciclistas (los más vulnerables)","No tiene deberes especiales"],"correct":1,"exp":"Manejas la unidad más pesada y peligrosa: por eso te exigen más cuidado con quien puede salir peor herido."},
 {"id":"convivencia-5","cat":"convivencia","q":"Al virar en una esquina donde hay una ciclovía, debes:","opts":["Pasar primero por ser auto","Ceder el paso a ciclistas y peatones que cruzan","Acelerar el giro"],"correct":1,"exp":"Antes de cruzar la ciclovía o el paso peatonal, cede. Es uno de los puntos donde más se atropella a ciclistas."},
 {"id":"convivencia-6","cat":"convivencia","q":"El peatón debe cruzar la calle:","opts":["Por donde le quede más cerca","Por los pasos peatonales o esquinas, respetando el semáforo","Corriendo entre los autos"],"correct":1,"exp":"Los cruces existen para hacerlo predecible y seguro. Igual, el conductor debe cuidar al peatón aunque este se equivoque."},
 {"id":"convivencia-7","cat":"convivencia","q":"Una 'zona de tránsito calmado' es:","opts":["Una autopista rápida","Un sector residencial o escolar donde el municipio fija velocidades reducidas (20 a 40 km/h)","Una zona sin reglas"],"correct":1,"exp":"Se crean donde hay muchos peatones o niños. Baja tú la velocidad: ahí conviven autos, personas y ciclos."},
 {"id":"convivencia-8","cat":"convivencia","q":"Si no tienes 1,5 m de espacio para adelantar con seguridad a un ciclista, debes:","opts":["Adelantar igual, rozándolo","Esperar detrás hasta que sea seguro rebasarlo","Tocar la bocina para que se orille"],"correct":1,"exp":"Sin espacio, no adelantas. Perder unos segundos vale infinitamente menos que la vida de una persona."},
 {"id":"convivencia-9","cat":"convivencia","q":"Un scooter o patineta eléctrica ('ciclo') en la vía:","opts":["Puede ir por la vereda a toda velocidad","Sigue reglas similares a la bici: ciclovía o calzada, no la vereda","No tiene ninguna regla"],"correct":1,"exp":"Los 'ciclos' (bici, scooter, patineta eléctrica) comparten las mismas reglas. Trátalos con el mismo cuidado que a un ciclista."},
 {"id":"convivencia-10","cat":"convivencia","q":"Como automovilista, frente a una motocicleta debes:","opts":["Ignorarla, es más ágil","Darle el mismo respeto y distancia; es un vehículo vulnerable, revisa tus puntos ciegos","Adelantarla siempre rápido"],"correct":1,"exp":"Las motos se esconden fácil en el punto ciego. Mira dos veces antes de cambiarte de pista o virar; su cuerpo está expuesto."},
 {"id":"maniobras-1","cat":"maniobras","q":"Antes de virar o cambiar de pista, lo primero es:","opts":["Frenar de golpe","Señalizar con anticipación usando el intermitente","Acelerar"],"correct":1,"exp":"Avisar a tiempo con la luz deja que los demás reaccionen. Señalizar tarde o no hacerlo provoca choques."},
 {"id":"maniobras-2","cat":"maniobras","q":"Al retroceder con el vehículo, debes:","opts":["Confiar solo en los espejos","Asegurarte de que no haya peatones ni obstáculos detrás, girando la cabeza","Retroceder rápido para terminar antes"],"correct":1,"exp":"Hacia atrás la visibilidad es pésima. Mira directamente, ve lento y, si hay dudas, pide que alguien te guíe."},
 {"id":"maniobras-3","cat":"maniobras","q":"Para virar a la izquierda en una calle de doble sentido, debes:","opts":["Cruzar rápido antes que los de enfrente","Ubicarte cerca del eje central y ceder el paso a los que vienen de frente","Virar desde la pista derecha"],"correct":1,"exp":"Te acercas al centro, esperas un hueco y cedes a los que vienen. Cruzar apurado frente a otros causa choques."},
 {"id":"maniobras-4","fig":"dia_pendiente","cat":"maniobras","q":"Al estacionar en una pendiente cuesta abajo, además del freno de mano, debes:","opts":["Dejar las ruedas rectas","Girar las ruedas hacia la cuneta o vereda","Dejar una marcha puesta y nada más"],"correct":1,"exp":"Si el auto se suelta, las ruedas giradas hacia la vereda lo detienen contra ella en vez de largarse calle abajo."},
 {"id":"maniobras-5","cat":"maniobras","q":"Está prohibido adelantar en:","opts":["Rectas con buena visibilidad","Curvas, puentes, túneles, cruces y con línea continua","Cualquier lugar con dos pistas"],"correct":1,"exp":"En esos puntos no ves el sentido contrario o hay poco espacio. Adelantar ahí es apostar de frente a ciegas."},
 {"id":"maniobras-6","cat":"maniobras","q":"Antes de abrir la puerta de tu auto estacionado en la calle, debes:","opts":["Abrirla de una vez","Mirar que no venga un ciclista o vehículo por ese lado","Abrir solo un poco y empujar"],"correct":1,"exp":"Abrir sin mirar ('dooring') derriba ciclistas y causa choques. Un vistazo por el espejo y hacia atrás lo evita."},
 {"id":"maniobras-7","cat":"maniobras","q":"Al incorporarte a una autopista por la pista de aceleración, debes:","opts":["Entrar despacio y frenar si es necesario","Igualar la velocidad del tránsito y ceder a los que ya circulan","Detenerte al final de la pista y esperar"],"correct":1,"exp":"Acelera para entrar al ritmo del flujo y busca el hueco. Frenar o detenerte en la incorporación provoca alcances."},
 {"id":"maniobras-8","cat":"maniobras","q":"No debes adelantar cuando:","opts":["Hay línea segmentada","No tienes visibilidad suficiente del sentido contrario","La vía está despejada"],"correct":1,"exp":"Sin ver claro lo que viene, no adelantas. La regla básica: solo rebasas si puedes completar la maniobra sin riesgo."},
 {"id":"maniobras-9","cat":"maniobras","q":"Al estacionar, la ley prohíbe hacerlo, entre otros lugares, en:","opts":["Una calle ancha de tu barrio","Cruces, curvas, puentes, túneles y ciclovías","Frente a tu propia casa"],"correct":1,"exp":"Estacionar en esos puntos bloquea la circulación o tapa la visibilidad. Además pueden retirar tu vehículo con grúa."},
 {"id":"maniobras-10","cat":"maniobras","q":"Un viraje en U (media vuelta) está prohibido:","opts":["En cualquier calle","Donde hay línea continua, curvas, cimas o poca visibilidad","Solo en autopistas"],"correct":1,"exp":"Dar la vuelta sin ver bien lo que viene es muy peligroso. Hazlo solo donde esté permitido y con total visibilidad."},
 {"id":"maniobras-11","cat":"maniobras","q":"Al estacionar en paralelo junto a la vereda, debes:","opts":["Dejar el auto medio en la calzada","Quedar pegado a la vereda, sin obstruir la circulación ni un cruce","Estacionar en diagonal"],"correct":1,"exp":"Bien pegado y alineado no estorbas el tránsito ni tapas visibilidad. Sobresalir a la pista provoca choques y multas."},
 {"id":"maniobras-12","cat":"maniobras","q":"Salir en reversa desde un estacionamiento hacia la vía exige:","opts":["Salir rápido para no estorbar","Ceder a todos y salir muy lento, porque la visibilidad hacia atrás es mala","Confiar solo en el espejo central"],"correct":1,"exp":"En reversa ves poco y los demás no te esperan. Cede el paso, avanza de a poco y detente ante cualquier duda."},
 {"id":"luces-1","cat":"luces","q":"Las luces bajas se usan principalmente:","opts":["Solo en el día","De noche y en túneles o neblina, para ver sin encandilar","Nunca, son opcionales"],"correct":1,"exp":"Son tu iluminación normal de noche y en baja visibilidad. Alumbran la vía sin cegar a los demás."},
 {"id":"luces-2","cat":"luces","q":"Las luces altas deben usarse:","opts":["Siempre que sea de noche","Solo en caminos sin iluminación y sin vehículos de frente; se bajan al cruzarse con otro auto","En ciudad para ver mejor"],"correct":1,"exp":"Alumbran lejos, pero encandilan. Al ver un auto de frente o ir detrás de otro, cambia a bajas para no cegarlo."},
 {"id":"luces-3","cat":"luces","q":"Los intermitentes (señalizadores) sirven para:","opts":["Avisar que vas a virar o cambiar de pista","Indicar que el auto está en venta","Adornar el vehículo"],"correct":0,"exp":"Comunican tu intención a los demás. Un giro sin señalizar sorprende y provoca choques por alcance."},
 {"id":"luces-4","cat":"luces","q":"Las luces de emergencia (los cuatro intermitentes a la vez) se usan cuando:","opts":["Vas con apuro","El vehículo está detenido por avería o hay un peligro que advertir","Está lloviendo un poco"],"correct":1,"exp":"Avisan 'atención, problema aquí'. Enciéndelas si te quedas detenido en la vía o para alertar de un riesgo repentino."},
 {"id":"luces-5","cat":"luces","q":"Conducir de noche sin luces encendidas:","opts":["Se permite en calles iluminadas","Es infracción y muy peligroso","Ahorra batería"],"correct":1,"exp":"Sin luces no ves bien y, peor, otros no te ven. Es infracción y una causa frecuente de atropellos nocturnos."},
 {"id":"luces-6","cat":"luces","q":"Si un vehículo de frente te encandila con sus luces, debes:","opts":["Mirar directo a la luz","No mirar la luz, fijar la vista en el borde derecho de tu pista y reducir","Encender tus altas para responderle"],"correct":1,"exp":"Mirar la luz te deja ciego unos segundos. Guíate por la línea del borde derecho y baja la velocidad hasta que pase."},
 {"id":"luces-7","cat":"luces","q":"Las luces de freno (rojas traseras) sirven para:","opts":["Iluminar la maleta","Avisar a los de atrás que estás frenando","Nada importante"],"correct":1,"exp":"Le dicen al de atrás que reduzcas para que él también frene. Si fallan, te chocan por detrás sin alcanzar a reaccionar."},
 {"id":"luces-8","cat":"luces","q":"Circular de noche sin luces traseras ni de patente:","opts":["No importa si vas lento","Es peligroso e infracción: no te ven por atrás","Solo aplica en carretera"],"correct":1,"exp":"Sin luces traseras eres casi invisible de noche. Es una causa típica de choques por alcance; mantenlas siempre operativas."},
 {"id":"emergencia-1","cat":"emergencia","q":"Si te ves involucrado en un accidente de tránsito, debes:","opts":["Seguir tu camino si el daño es menor","Detenerte, prestar auxilio y dar aviso a Carabineros","Discutir de quién fue la culpa antes que nada"],"correct":1,"exp":"Primero: parar, ayudar y avisar. Irte del lugar, aunque el golpe parezca leve, te complica legalmente."},
 {"id":"emergencia-2","cat":"emergencia","q":"Fugarse del lugar de un accidente en el que hay personas lesionadas:","opts":["Es una falta menor","Es un delito grave (Ley Emilia) con penas serias","Está permitido si tienes miedo"],"correct":1,"exp":"La fuga se castiga fuerte e impide obtener o renovar la licencia. Aunque estés asustado, quédate y auxilia."},
 {"id":"emergencia-3","cat":"emergencia","q":"Ante una persona herida en un accidente, lo correcto es:","opts":["Moverla de inmediato al lado","No moverla salvo peligro inminente (fuego, otro choque) y esperar a los servicios de emergencia","Darle agua y sentarla"],"correct":1,"exp":"Mover a un herido puede agravar una lesión de columna. Solo lo mueves si quedarse es más peligroso que moverlo."},
 {"id":"emergencia-4","cat":"emergencia","q":"¿A qué número llamas a Carabineros ante una emergencia en Chile?","opts":["131","132","133"],"correct":2,"exp":"133 = Carabineros. Recuerda también 131 (ambulancia/SAMU) y 132 (bomberos). Da ubicación clara y número de heridos."},
 {"id":"emergencia-5","cat":"emergencia","q":"Si tu vehículo se detiene o se avería en plena vía, debes:","opts":["Bajarte y alejarte sin señalizar","Encender las luces de emergencia y colocar el triángulo de seguridad detrás","Empujarlo tú solo por la pista"],"correct":1,"exp":"Balizas + triángulo avisan a los que vienen y evitan que te choquen por atrás. Ubícate en un lugar visible y seguro."},
 {"id":"emergencia-6","cat":"emergencia","q":"Ante un amago de incendio en el motor, lo recomendable es:","opts":["Abrir el capó de inmediato y de par en par","Detener, apagar el motor, alejar a los ocupantes y usar el extintor solo si es seguro","Echarle agua encima"],"correct":1,"exp":"Abrir el capó de golpe aviva el fuego con oxígeno. Primero saca a la gente; el auto se reemplaza, las personas no."},
 {"id":"emergencia-7","cat":"emergencia","q":"Lo primero al llegar a la escena de un accidente es:","opts":["Grabar un video","Asegurar el lugar para evitar un segundo choque (señalizar, advertir)","Mover los autos de inmediato"],"correct":1,"exp":"Proteger la escena evita que otro vehículo atropelle a los que ya están ayudando. Primero seguridad, luego auxilio."},
 {"id":"emergencia-8","cat":"emergencia","q":"La regla PAS para actuar ante un accidente es:","opts":["Parar, Acelerar, Salir","Proteger, Avisar, Socorrer","Preguntar, Anotar, Seguir"],"correct":1,"exp":"PAS: primero Proteger (asegurar la zona), luego Avisar (llamar a emergencias) y por último Socorrer a los heridos."},
 {"id":"emergencia-9","cat":"emergencia","q":"Ante una hemorragia visible en un herido, lo básico es:","opts":["Dejar que sangre para 'limpiar' la herida","Presionar la herida con un paño limpio hasta que llegue la ayuda","Aplicar hielo directo"],"correct":1,"exp":"La presión directa ayuda a frenar el sangrado. Mantén la calma, presiona firme y espera a los servicios de emergencia."},
 {"id":"emergencia-10","cat":"emergencia","q":"A una persona herida de gravedad NO debes:","opts":["Hablarle para tranquilizarla","Darle de comer o beber","Abrigarla"],"correct":1,"exp":"Comida o líquido pueden atragantarla o complicar una cirugía urgente. Solo acompáñala y espera a los profesionales."},
 {"id":"segur-1","cat":"segur","q":"El cinturón de seguridad y el airbag son elementos de seguridad:","opts":["Activa (evitan el choque)","Pasiva (protegen cuando el choque ya ocurre)","Estética"],"correct":1,"exp":"Seguridad PASIVA: reducen el daño una vez producido el impacto. La ACTIVA (frenos, neumáticos, dirección) lo evita antes."},
 {"id":"segur-2","cat":"segur","q":"La distancia total de frenado del vehículo:","opts":["Es siempre la misma","Aumenta con la velocidad y con el pavimento mojado","Solo depende del auto"],"correct":1,"exp":"A más velocidad, la distancia para detenerte crece mucho, y con lluvia aún más. Por eso bajas la velocidad si llueve."},
 {"id":"segur-3","cat":"segur","q":"La profundidad mínima legal del dibujo (banda de rodamiento) del neumático es:","opts":["0,5 mm","1,6 mm","5 mm"],"correct":1,"exp":"Mínimo 1,6 mm. Bajo eso el neumático pierde agarre y no drena el agua: aumenta el riesgo de perder el control."},
 {"id":"segur-4","cat":"segur","q":"El sistema de frenos ABS sirve para:","opts":["Frenar en menos metros siempre","Evitar que las ruedas se bloqueen y mantener el control de la dirección al frenar fuerte","Aumentar la velocidad máxima"],"correct":1,"exp":"Con ABS, en un frenazo las ruedas no se traban, así puedes seguir girando para esquivar. Te da control, no magia."},
 {"id":"segur-5","cat":"segur","q":"Si sientes sueño o fatiga mientras conduces, lo correcto es:","opts":["Abrir la ventana y subir la música","Detenerte en un lugar seguro a descansar","Acelerar para llegar antes"],"correct":1,"exp":"Nada reemplaza al descanso. Una microdormida al volante mata igual que el alcohol. Detente y duerme un poco."},
 {"id":"segur-6","cat":"segur","q":"El apoyacabezas bien ajustado sirve para:","opts":["Descansar la cabeza en viajes largos","Prevenir lesiones de cuello (latigazo) en un choque por atrás","Nada, es decorativo"],"correct":1,"exp":"En un impacto trasero, sujeta la cabeza y evita el 'latigazo' cervical. Ajústalo a la altura de tu nuca."},
 {"id":"segur-7","cat":"segur","q":"El 'aquaplaning' (o hidroplaneo) ocurre cuando:","opts":["El motor se recalienta","El neumático pierde contacto por una capa de agua y el auto 'flota' sin control","Se empañan los vidrios"],"correct":1,"exp":"Sobre agua y a velocidad, el neumático deja de agarrar. Reduce con lluvia y mantén los neumáticos con buen dibujo."},
 {"id":"segur-8","cat":"segur","q":"Antes de un viaje largo conviene revisar:","opts":["Solo el estanque de bencina","Neumáticos, luces, frenos y niveles (aceite, agua)","Nada, si el auto anduvo ayer"],"correct":1,"exp":"Una revisión de 5 minutos evita quedarte botado o algo peor en carretera. Prevención barata contra problemas caros."},
 {"id":"segur-9","cat":"segur","q":"Si se revienta un neumático a alta velocidad, lo correcto es:","opts":["Frenar de golpe","Sujetar firme el volante, soltar el acelerador y frenar suavemente hasta detenerte","Girar bruscamente hacia la berma"],"correct":1,"exp":"Frenar o girar de golpe te hace perder el control. Mantén derecho, desacelera de a poco y sal de la vía con calma."},
 {"id":"segur-10","cat":"segur","q":"La presión de los neumáticos conviene revisarla:","opts":["Nunca, se mantiene sola","Periódicamente; mal inflados frenan peor y se gastan más","Solo cuando se pinchan"],"correct":1,"exp":"Un neumático desinflado calienta, frena mal y gasta más combustible. Revísala cada cierto tiempo y antes de viajar."},
 {"id":"segur-11","cat":"segur","q":"Ajustar los espejos y el asiento se hace:","opts":["Mientras manejas","Antes de partir, para reducir puntos ciegos y ir cómodo","No es necesario"],"correct":1,"exp":"Con espejos y asiento bien puestos ves más y llegas mejor a los mandos. Ajustarlos en movimiento es una distracción peligrosa."},
 {"id":"segur-12","cat":"segur","q":"Si el indicador de temperatura del motor sube a la zona roja, debes:","opts":["Seguir hasta llegar","Detenerte y apagar el motor; seguir puede fundirlo","Echarle agua fría de inmediato al motor caliente"],"correct":1,"exp":"El rojo avisa recalentamiento. Detente y deja enfriar; forzar el motor caliente puede dañarlo de forma grave y cara."},
 {"id":"docs-1","cat":"docs","q":"¿Qué documentos debes portar y mantener vigentes para conducir legalmente?","opts":["Solo la licencia","Licencia vigente, permiso de circulación, revisión técnica y seguro obligatorio (SOAP)","Solo el permiso de circulación"],"correct":1,"exp":"Los cuatro. Que falte cualquiera es infracción; Carabineros puede cursar parte e incluso retener el vehículo."},
 {"id":"docs-2","cat":"docs","q":"La licencia Clase B habilita para conducir:","opts":["Buses y camiones de pasajeros","Automóviles y vehículos livianos particulares (no transporte remunerado de pasajeros)","Motos de cualquier cilindrada"],"correct":1,"exp":"Clase B = livianos particulares (auto, camioneta, furgón hasta cierto peso). Transportar pasajeros por dinero exige clase profesional."},
 {"id":"docs-3","cat":"docs","q":"El SOAP (Seguro Obligatorio de Accidentes Personales) cubre:","opts":["Los daños de tu vehículo","Las lesiones o muerte de personas en un accidente de tránsito","El robo del auto"],"correct":1,"exp":"El SOAP protege a las PERSONAS, no la chapa. Para daños materiales necesitas un seguro adicional voluntario."},
 {"id":"docs-4","cat":"docs","q":"Conducir sin haber obtenido licencia de conducir es:","opts":["Una falta leve","Una falta gravísima","Permitido si vas acompañado de un licenciado"],"correct":1,"exp":"Es gravísima. No existe el 'permiso de aprendiz informal': manejar sin licencia te expone a multa alta y más si hay accidente."},
 {"id":"docs-5","cat":"docs","q":"La edad mínima para obtener la licencia Clase B es, por regla general:","opts":["16 años","18 años (excepcionalmente 17 con requisitos)","21 años"],"correct":1,"exp":"18 años. A los 17 solo de forma excepcional cumpliendo requisitos. La madurez al volante importa tanto como la técnica."},
 {"id":"docs-6","cat":"docs","q":"La revisión técnica sirve para:","opts":["Cobrar un impuesto","Certificar que el vehículo está mecánicamente apto y dentro de la norma de emisiones","Pintar la patente"],"correct":1,"exp":"Verifica frenos, luces, dirección y gases. Un auto sin revisión al día es un riesgo para ti y para el resto."},
 {"id":"docs-7","cat":"docs","q":"Para renovar la licencia de conducir, en general debes:","opts":["Solo pagar","Rendir exámenes de vista y reflejos, cuando esté vencida o próxima a caducar","Sacar una nueva desde cero cada año"],"correct":1,"exp":"La renovación revisa que sigas apto (vista, reflejos). Hazla cuando corresponda para no manejar con licencia vencida."},
 {"id":"docs-8","cat":"docs","q":"¿Cuál de estas situaciones puede impedir obtener o renovar la licencia?","opts":["Haber pagado una multa de estacionamiento","Haberse fugado de un accidente con lesionados o tener condena por manejo ebrio","Cambiarse de comuna"],"correct":1,"exp":"La ley bloquea la licencia a quien cometió faltas graves como fuga o conducción ebria. Son antecedentes que pesan."},
 {"id":"docs-9","cat":"docs","q":"El permiso de circulación acredita que:","opts":["Aprobaste el examen teórico","El vehículo pagó su permiso anual para circular","El auto está asegurado contra robo"],"correct":1,"exp":"Es el pago anual que habilita al vehículo a andar por las vías. Sin él vigente, te arriesgas a multa y retención."},
 {"id":"docs-10","cat":"docs","q":"Si acumulas multas de tránsito impagas:","opts":["No pasa nada","Pueden impedirte renovar el permiso de circulación y complicar trámites","Se borran solas al año"],"correct":1,"exp":"Las multas impagas quedan registradas y traban trámites del vehículo. Conviene mantenerlas al día."},
 {"id":"infrac-1","cat":"infrac","q":"Las infracciones de tránsito se clasifican en:","opts":["Solo leves y graves","Leves, graves y gravísimas, según el riesgo","Solo multas de dinero"],"correct":1,"exp":"Tres niveles según el peligro que generan. Mientras más riesgo, mayor multa y más posibilidad de suspender la licencia."},
 {"id":"infrac-2","cat":"infrac","q":"¿Cuál de estas es una falta gravísima?","opts":["No portar la placa delantera","Conducir en estado de ebriedad","No llevar el permiso de circulación físico"],"correct":1,"exp":"Manejar ebrio es gravísima, junto con sin licencia, exceso de más de 20 km/h o pasarse un rojo. Son las más peligrosas."},
 {"id":"infrac-3","cat":"infrac","q":"Pasarse una luz roja del semáforo es:","opts":["Falta leve","Falta gravísima","No es infracción si no viene nadie"],"correct":1,"exp":"Gravísima: es una de las causas típicas de choques laterales graves en intersección. El rojo no se negocia."},
 {"id":"infrac-4","cat":"infrac","q":"No usar el cinturón de seguridad se considera:","opts":["Sin sanción","Una infracción (grave)","Recomendación opcional"],"correct":1,"exp":"Es infracción, y sobre todo te salva la vida: en un choque, sin cinturón sales despedido o golpeas el parabrisas."},
 {"id":"infrac-5","cat":"infrac","q":"Reincidir en conducir en estado de ebriedad puede llevar a:","opts":["Solo una multa pequeña","Suspensión prolongada e incluso la cancelación de la licencia","Un curso y nada más"],"correct":1,"exp":"La ley endurece la sanción con cada reincidencia: de suspensión larga a perder la licencia. Manejar ebrio no tiene excusa."},
 {"id":"infrac-6","cat":"infrac","q":"Las multas de tránsito se tramitan y resuelven en:","opts":["La comisaría","El Juzgado de Policía Local (JPL)","La notaría"],"correct":1,"exp":"El parte llega al Juzgado de Policía Local de la comuna donde ocurrió la falta. Ahí se cursa y se paga la multa."},
 {"id":"infrac-7","cat":"infrac","q":"Si Carabineros te detiene y no llevas la licencia vigente:","opts":["Te dejan seguir sin problema","Pueden cursarte un parte e incluso retener el vehículo","Solo te dan una advertencia siempre"],"correct":1,"exp":"Conducir sin licencia al día es infracción seria. Además del parte, pueden retener el auto hasta regularizar."},
 {"id":"infrac-8","cat":"infrac","q":"El objetivo de fondo de las sanciones de tránsito es:","opts":["Recaudar dinero para el Estado","Desincentivar conductas peligrosas y salvar vidas","Molestar a los conductores"],"correct":1,"exp":"Las multas buscan que dejes de arriesgar tu vida y la de otros. Verlas solo como 'cobro' hace perder el punto."},
 {"id":"ambiente-1","cat":"ambiente","q":"La conducción eficiente (eco-driving) consiste en:","opts":["Acelerar y frenar bruscamente","Acelerar y frenar de forma suave y mantener velocidad constante","Ir siempre a la máxima velocidad"],"correct":1,"exp":"Manejar suave ahorra combustible, reduce emisiones y el desgaste del auto. Además es más seguro y cómodo."},
 {"id":"ambiente-2","cat":"ambiente","q":"Dejar el motor encendido mucho rato con el auto detenido (ralentí):","opts":["Ayuda al motor","Gasta combustible y contamina sin necesidad; conviene apagarlo","Es obligatorio en el semáforo"],"correct":1,"exp":"En una detención larga, apagar el motor ahorra bencina y evita emitir gases al pedo. Los autos modernos parten sin problema."},
 {"id":"ambiente-3","cat":"ambiente","q":"La revisión técnica, en materia ambiental, mide:","opts":["El color del auto","Las emisiones de gases contaminantes del vehículo","La antigüedad del modelo"],"correct":1,"exp":"Controla que el auto no emita más gases de lo permitido. Un motor mal mantenido contamina y puede reprobar."},
 {"id":"ambiente-4","cat":"ambiente","q":"Los neumáticos mal inflados, respecto al medio ambiente:","opts":["Dan lo mismo","Aumentan el consumo de combustible y, con ello, las emisiones","Reducen el consumo"],"correct":1,"exp":"Con baja presión el motor trabaja más y quema más bencina. Mantenerlos bien inflados ahorra plata y contamina menos."},
 {"id":"ambiente-5","cat":"ambiente","q":"La restricción vehicular en algunas ciudades:","opts":["Es una recomendación","Limita la circulación según el último dígito de la patente para reducir la contaminación","Solo aplica a camiones"],"correct":1,"exp":"En episodios de mala calidad del aire se restringe la circulación por patente. No respetarla es infracción."},
 {"id":"ambiente-6","cat":"ambiente","q":"Mantener el vehículo en buen estado (filtros, motor, afinamiento):","opts":["No influye en el consumo","Reduce el consumo de combustible y la contaminación","Solo importa para la estética"],"correct":1,"exp":"Un motor afinado quema mejor la bencina: gastas menos y ensucias menos el aire. La mantención se paga sola."},
 {"id":"humano-1","cat":"humano","q":"La fatiga o el sueño al volante:","opts":["Se quitan con música fuerte","Reducen la atención y los reflejos, como el alcohol; hay que detenerse a descansar","No afectan si eres experto"],"correct":1,"exp":"Cansado reaccionas tarde y hasta te duermes segundos sin darte cuenta. Ningún truco reemplaza parar y descansar."},
 {"id":"humano-2","cat":"humano","q":"Manejar muy enojado, estresado o apurado:","opts":["Mejora los reflejos","Afecta el juicio y lleva a maniobras riesgosas; conviene calmarse antes","No tiene relación con la conducción"],"correct":1,"exp":"Las emociones fuertes nublan las decisiones. Si estás muy alterado, respira y espera unos minutos antes de partir."},
 {"id":"humano-3","cat":"humano","q":"Una buena visión para conducir:","opts":["No es importante","Es esencial; por eso la renovación evalúa la vista y debes usar lentes si los necesitas","Solo importa de noche"],"correct":1,"exp":"Gran parte de la información al manejar entra por los ojos. Si usas lentes o lentillas, úsalos siempre al conducir."},
 {"id":"humano-4","cat":"humano","q":"En un viaje largo por carretera conviene:","opts":["No parar para llegar antes","Detenerse cada cierto tiempo a estirar las piernas y descansar","Manejar de noche siempre, hay menos tráfico"],"correct":1,"exp":"Pausas cada par de horas mantienen la concentración. Acumular horas sin parar es cómo llega la fatiga y los errores."},
 {"id":"humano-5","cat":"humano","q":"La 'conducción defensiva' consiste en:","opts":["Manejar agresivo para imponerte","Anticipar los posibles errores de otros y estar listo para reaccionar","No usar nunca la bocina"],"correct":1,"exp":"Es dar por hecho que otro puede equivocarse y dejarte margen para evitarlo. Prevenir antes que reaccionar salva vidas."},
 {"id":"humano-6","cat":"humano","q":"El apuro y la impaciencia al conducir:","opts":["Ayudan a llegar seguro","Llevan a maniobras riesgosas; salir con tiempo previene accidentes","No influyen en el riesgo"],"correct":1,"exp":"Ganar dos minutos no vale un choque. Planificar y salir con holgura es la forma más simple de manejar tranquilo y seguro."}
];

/* ---------- CINTURÓN DE SEGURIDAD (tema de doble puntaje) ---------- */
window.QUESTIONS.push(
 {id:"cinturon-1",cat:"segur",q:"¿Cómo debe ir puesto correctamente el cinturón de seguridad?",opts:["La banda diagonal sobre el hombro y el pecho, y la inferior sobre las caderas","La banda diagonal bajo el brazo para mayor comodidad","La banda inferior sobre el abdomen, bien apretada"],correct:0,exp:"La banda diagonal cruza hombro y pecho (nunca el cuello ni bajo el brazo) y la inferior va sobre los huesos de la cadera, no sobre el abdomen: así reparte la fuerza del choque en las partes más resistentes del cuerpo."},
 {id:"cinturon-2",cat:"segur",q:"En un choque, un pasajero del asiento trasero sin cinturón:",opts:["No corre riesgo porque va detrás","Sale proyectado y puede herir gravemente a quienes van adelante","Queda protegido por el respaldo delantero"],correct:1,exp:"Sin cinturón, el pasajero de atrás se convierte en un proyectil: golpea a los ocupantes delanteros y puede salir expulsado. Por eso el cinturón es obligatorio en todos los asientos."}
);

/* ---------- RECONOCIMIENTO VISUAL DE SEÑALES (img = clave en SIGNS) ---------- */
window.QUESTIONS.push(
 {id:"visual-1",cat:"visual",img:"pare",q:"¿Qué te exige esta señal?",opts:["Detenerte por completo, ceder el paso y avanzar solo cuando sea seguro","Reducir la velocidad y pasar si no viene nadie","Ceder el paso solo si hay un vehículo a la vista"],correct:0,exp:"PARE = detención total siempre, aunque la vía parezca vacía. Reducir sin detenerse es infracción."},
 {id:"visual-2",cat:"visual",img:"ceda-el-paso",q:"¿Qué te exige esta señal?",opts:["Detenerte siempre por completo","Ceder el paso a quienes circulan por la vía preferente; te detienes solo si es necesario","Que tienes preferencia sobre la vía transversal"],correct:1,exp:"Ceda el paso: si la vía está libre, continúas sin detenerte. Si viene alguien, cedes. La detención obligatoria es del PARE."},
 {id:"visual-3",cat:"visual",img:"no-entrar",q:"¿Qué significa esta señal?",opts:["Prohibido estacionar","Calle sin salida","No entrar: prohibido ingresar en ese sentido"],correct:2,exp:"Círculo rojo con barra blanca = No entrar. Suele aparecer en la salida de calles de un solo sentido."},
 {id:"visual-4",cat:"visual",img:"velocidad-maxima",q:"Esta señal indica:",opts:["La velocidad máxima permitida: 50 km/h","La velocidad recomendada en curva: 50 km/h","La velocidad mínima obligatoria: 50 km/h"],correct:0,exp:"Círculo blanco con orla roja y un número = velocidad máxima (reglamentaria). Superarla es infracción."},
 {id:"visual-5",cat:"visual",img:"no-adelantar",q:"¿Qué prohíbe esta señal?",opts:["Circular a vehículos pesados","Adelantar a otros vehículos en ese tramo","Cambiar de pista hacia la derecha"],correct:1,exp:"Dos autos dentro de un círculo con orla roja = prohibido adelantar hasta que termine la restricción."},
 {id:"visual-6",cat:"visual",img:"no-virar-a-la-izquierda",q:"¿Qué indica esta señal?",opts:["Viraje obligatorio a la izquierda","Curva peligrosa a la izquierda","Prohibido virar a la izquierda"],correct:2,exp:"La flecha tachada con la diagonal roja indica prohibición. No confundir con la preventiva de curva (rombo amarillo)."},
 {id:"visual-7",cat:"visual",img:"prohibido-estacionar",q:"¿Qué significa esta señal?",opts:["No estacionar","Estacionamiento exclusivo","Zona de estacionamiento pagado"],correct:0,exp:"La 'E' tachada prohíbe estacionar. Detenerte un momento para subir o bajar pasajeros, en cambio, no está prohibido por esta señal."},
 {id:"visual-8",cat:"visual",img:"curva-a-la-derecha",q:"Esta señal te advierte:",opts:["Viraje obligatorio a la derecha","Una curva hacia la derecha: reduce y no adelantes","Desvío temporal por obras"],correct:1,exp:"Rombo amarillo = preventiva: avisa de un peligro, no obliga a una maniobra. Reduce antes de entrar a la curva."},
 {id:"visual-9",cat:"visual",img:"proximidad-de-paso-de-cebra",q:"¿Qué advierte esta señal?",opts:["Prohibido el paso de peatones","Calle peatonal exclusiva","Proximidad de un cruce de peatones"],correct:2,exp:"Preventiva: más adelante cruzan peatones. Reduce y prepárate para cederles el paso."},
 {id:"visual-10",cat:"visual",img:"zona-de-escuela",q:"¿Qué advierte esta señal?",opts:["Zona de escolares: presencia de niños","Plaza o parque infantil exclusivo","Paradero de transporte escolar obligatorio"],correct:0,exp:"Advierte presencia de escolares. Reduce la velocidad y extrema la atención en horario de entrada y salida."},
 {id:"visual-11",cat:"visual",img:"resalto",q:"¿Qué advierte esta señal?",opts:["Pendiente pronunciada","Resalto (lomo de toro) en la calzada","Calzada en mal estado"],correct:1,exp:"Avisa un resalto reductor de velocidad. Pasarlo rápido daña la suspensión y puede hacerte perder el control."},
 {id:"visual-12",cat:"visual",img:"proximidad-de-semaforo",q:"¿Qué advierte esta señal?",opts:["Semáforo fuera de servicio","Proximidad de un semáforo","Cruce regulado por Carabineros"],correct:1,exp:"Preventiva: hay un semáforo más adelante que quizás aún no ves. Prepárate para detenerte."},
 {id:"visual-13",cat:"visual",img:"proximidad-de-senal-pare",q:"¿Qué advierte esta señal?",opts:["Que más adelante hay una señal PARE","Que debes detenerte aquí mismo","Que la vía preferente es la tuya"],correct:0,exp:"Rombo amarillo con un PARE dibujado: anticipa una señal PARE que viene. La detención se hace en la señal PARE, no aquí."},
 {id:"visual-14",cat:"visual",img:"cruz-de-san-andres-cruce-ferroviario",q:"¿Qué indica esta señal (cruz de San Andrés)?",opts:["Cruce de dos vías con preferencia compartida","Fin de la zona de restricción","Cruce ferroviario a nivel: el tren tiene preferencia"],correct:2,exp:"Marca el cruce con la vía férrea. Detente si la barrera baja o las luces se activan; el tren no puede frenar a tiempo."},
 {id:"visual-15",cat:"visual",img:"primeros-auxilios-u-hospital",q:"Esta señal es de tipo:",opts:["Informativa: indica un servicio (hospital)","Preventiva: zona de ambulancias","Reglamentaria: prohibido tocar la bocina"],correct:0,exp:"Fondo azul = informativa de servicios. Te orienta, no te impone una obligación."},
 {id:"visual-16",cat:"visual",img:"vel30",q:"Ves esta señal en una calle con mucho tránsito peatonal. ¿Qué haces?",opts:["Circular a 30 km/h como mínimo","Respetar 30 km/h como máximo en ese tramo","Ignorarla si la calle está despejada"],correct:1,exp:"Es una velocidad MÁXIMA. Rige aunque la calle esté vacía, y es común en zonas escolares o de tránsito calmado."}
);
window.CATS.visual = {label:"Señales de tránsito (imágenes)", color:"#0EA5E9"};
